function usage() {
  console.log(`
Usage: node igwatcher.js <username-or-url> [options]

Options:
  --profile       Get profile info only (default)
  --posts         Get posts
  --stories       Get stories
  --reels         Get reels
  --highlights    Get highlights list
  --tagged        Get tagged posts
  --all           Get all available data

Examples:
  node igwatcher.js instagram
  node igwatcher.js https://www.instagram.com/natgeo/
  node igwatcher.js natgeo --posts
  node igwatcher.js natgeo --all
`)
}

async function main() {
  const args = process.argv.slice(2)
  if (args.length === 0 || args.includes('--help') || args.includes('-h')) {
    usage()
    process.exit(0)
  }

  const input = args[0]
  const flags = args.slice(1)
  const doAll = flags.includes('--all')
  const doProfile = flags.includes('--profile') || flags.length === 0
  const doPosts = flags.includes('--posts') || doAll
  const doStories = flags.includes('--stories') || doAll
  const doReels = flags.includes('--reels') || doAll
  const doHighlights = flags.includes('--highlights') || doAll
  const doTagged = flags.includes('--tagged') || doAll

  let username
  try {
    username = extractUsername(input)
  } catch (e) {
    console.log(JSON.stringify({ status: false, message: e.message }, null, 2))
    process.exit(1)
  }

  const result = { username }

  try {
    if (doProfile || doPosts || doStories || doReels || doHighlights || doTagged) {
      const profile = await getProfile(username)
      result.profile = profile

      if (profile.note === 'profile_unavailable') {
        result.status = false
        result.message = 'Profile not found or is private'
        console.log(JSON.stringify(result, null, 2))
        process.exit(0)
      }
    }

    const tasks = []

    if (doPosts) {
      tasks.push(getPosts(username).then(d => { result.posts = d }).catch(e => { result.posts_error = e.message }))
    }
    if (doStories) {
      tasks.push(getStories(username).then(d => { result.stories = d }).catch(e => { result.stories_error = e.message }))
    }
    if (doReels) {
      tasks.push(getReels(username).then(d => { result.reels = d }).catch(e => { result.reels_error = e.message }))
    }
    if (doHighlights) {
      tasks.push(getHighlights(username).then(d => { result.highlights = d }).catch(e => { result.highlights_error = e.message }))
    }
    if (doTagged) {
      tasks.push(getTagged(username).then(d => { result.tagged = d }).catch(e => { result.tagged_error = e.message }))
    }

    if (tasks.length > 0) {
      await Promise.all(tasks)
    }

    console.log(JSON.stringify(result, null, 2))
  } catch (e) {
    console.log(JSON.stringify({ status: false, message: e.message }, null, 2))
    process.exit(1)
  }
}

